use serde_json::Value;
use super::rendering::Text;
use super::render_format::shorten;
use super::renderers_common::{RendererTheme,RenderResultOptions,position_args,render_position_call,result_details,result_text,COLLAPSED_HEAD,EXPANDED_HEAD,PATH_BUDGET};
pub fn render_prepare_rename_call(args:&Value,theme:&dyn RendererTheme)->Text {Text::new(render_position_call("lsp_prepare_rename",&position_args(args),theme))}
pub fn render_prepare_rename_result(result:&Value,_options:RenderResultOptions,theme:&dyn RendererTheme)->Text {let details=result_details(result);if let Some(error)=details.and_then(|d|d.get("error")).and_then(Value::as_str).filter(|e|!e.is_empty()) {return Text::new(theme.fg("warning",error.split('\n').next().unwrap_or("error")));}let fallback=result_text(result,0).unwrap_or("");if fallback.starts_with("Rename") {Text::new(theme.fg("success",fallback))} else {Text::new(theme.fg("muted",fallback))}}
pub fn render_rename_call(args:&Value,theme:&dyn RendererTheme)->Text {let loc=render_position_call("lsp_rename",&position_args(args),theme);let arrow=theme.fg("muted"," → ");let new_name=theme.fg("accent",&format!("\"{}\"",args.get("newName").and_then(Value::as_str).unwrap_or("")));Text::new(format!("{loc}{arrow}{new_name}"))}
pub fn render_rename_result(result:&Value,options:RenderResultOptions,theme:&dyn RendererTheme)->Text {let details=result_details(result);if let Some(error)=details.and_then(|d|d.get("error")).and_then(Value::as_str).filter(|e|!e.is_empty()) {return Text::new(theme.fg("warning",error.split('\n').next().unwrap_or("error")));}let Some(apply)=details.and_then(|d|d.get("apply")).filter(|a|!a.is_null()) else {return Text::new(theme.fg("dim",result_text(result,0).unwrap_or("No edit applied")));};if apply.get("success").and_then(Value::as_bool)!=Some(true) {let mut lines=vec![theme.fg("error","Rename failed")];for error in apply.get("errors").and_then(Value::as_array).into_iter().flatten().take(5) {lines.push(theme.fg("dim",&format!("  {}",error.as_str().unwrap_or(""))));}return Text::new(lines.join("\n"));}let total=apply.get("totalEdits").and_then(Value::as_u64).unwrap_or(0);let files=apply.get("filesModified").and_then(Value::as_array).cloned().unwrap_or_default();let mut summary=theme.fg("success",&format!("Applied {total} edit{}",if total==1 {""} else {"s"}));summary.push_str(&theme.fg("muted",&format!(" to {} file{}",files.len(),if files.len()==1 {""} else {"s"})));if !options.expanded {let mut lines=vec![summary];for file in files.iter().take(COLLAPSED_HEAD) {lines.push(theme.fg("muted",&format!("  {}",shorten(file.as_str().unwrap_or(""),PATH_BUDGET))));}if files.len()>COLLAPSED_HEAD {lines.push(theme.fg("dim",&format!("  … {} more",files.len()-COLLAPSED_HEAD)));}return Text::new(lines.join("\n"));}let mut lines=vec![summary,String::new()];for file in files.iter().take(EXPANDED_HEAD) {lines.push(theme.fg("accent",&format!("  {}",shorten(file.as_str().unwrap_or(""),PATH_BUDGET))));}if files.len()>EXPANDED_HEAD {lines.push(theme.fg("dim",&format!("… {} more",files.len()-EXPANDED_HEAD)));}Text::new(lines.join("\n"))}
#[cfg(test)] mod tests {use super::*;use crate::adapter::renderers_common::test_theme::TagTheme;use serde_json::json;
#[test] fn rename_call_shows_target_name(){assert!(render_rename_call(&json!({"filePath":"/tmp/a.ts","line":2,"character":3,"newName":"next"}),&TagTheme).text.ends_with("<accent>\"next\"</accent>"));}
#[test] fn prepare_call_uses_tool_name(){assert!(render_prepare_rename_call(&json!({"filePath":"/tmp/a.ts","line":1,"character":0}),&TagTheme).text.contains("lsp_prepare_rename"));}
#[test] fn prepare_success_and_failure_have_distinct_colors(){assert!(render_prepare_rename_result(&json!({"content":[{"text":"Rename to next"}]}),RenderResultOptions::default(),&TagTheme).text.starts_with("<success>"));assert!(render_prepare_rename_result(&json!({"content":[{"text":"Cannot rename"}]}),RenderResultOptions::default(),&TagTheme).text.starts_with("<muted>"));}
#[test] fn rename_without_apply_falls_back(){assert_eq!(render_rename_result(&json!({"content":[{"text":"nothing"}]}),RenderResultOptions::default(),&TagTheme).text,"<dim>nothing</dim>");}
#[test] fn rename_failure_lists_errors(){let r=json!({"details":{"apply":{"success":false,"errors":["e1","e2"]}}});assert!(render_rename_result(&r,RenderResultOptions::default(),&TagTheme).text.contains("<dim>  e2</dim>"));}
#[test] fn rename_applied_summarizes_edits(){let r=json!({"details":{"apply":{"success":true,"totalEdits":1,"filesModified":["/a.ts"]}}});assert_eq!(render_rename_result(&r,RenderResultOptions::default(),&TagTheme).text,"<success>Applied 1 edit</success><muted> to 1 file</muted>\n<muted>  /a.ts</muted>");}
#[test] fn rename_collapsed_marks_more_files(){let r=json!({"details":{"apply":{"success":true,"totalEdits":4,"filesModified":["/a","/b","/c","/d"]}}});assert!(render_rename_result(&r,RenderResultOptions::default(),&TagTheme).text.ends_with("<dim>  … 1 more</dim>"));}
#[test] fn rename_expanded_indents_files(){let r=json!({"details":{"apply":{"success":true,"totalEdits":2,"filesModified":["/a","/b"]}}});assert!(render_rename_result(&r,RenderResultOptions {expanded:true,is_partial:false},&TagTheme).text.contains("<accent>  /b</accent>"));}
#[test] fn prepare_error_warns(){assert_eq!(render_prepare_rename_result(&json!({"details":{"error":"bad"}}),RenderResultOptions::default(),&TagTheme).text,"<warning>bad</warning>");}}
